// Faturalama anahtarının saf fiyat mantığı: para yazımı ve yıllık indirim hesabı. React ve CSS içermez; test doğrudan bunu okur.
import { math, money } from "@snn/abacus-core";

/** Para birimi simgesi ("TRY" → "₺"). ABACUS simgeyi tutarın önüne koyar; simge, sıfır tutarın yazımından ayıklanır. */
export function currencyPrefix(currency = "TRY"): string {
  const zero = money.formatMajor(0, { currency, digits: 0, zero: "symbol" });
  return zero === "—" ? "" : zero.replace(/0$/, "");
}

/** Tutarı para birimiyle yazar: (1250, "TRY") → "₺1.250"; `decimals: 2` ile "₺1.250,00". */
export function formatPrice(amount: number, currency = "TRY", decimals = 0): string {
  return money.formatMajor(amount, { currency, digits: decimals, kurus: decimals > 0 });
}

/** Yıllık planda ayın eşdeğer fiyatı: aylık fiyattan yüzde indirim düşülür, tam liraya yuvarlanır. */
export function yearlyMonthlyEquivalent(monthly: number, discountPercent: number): number {
  const rate = math.div(discountPercent, 100) ?? 0;
  return math.round(math.mul(monthly, math.sub(1, rate)), 0);
}

/** Aylık fiyata göre indirim yüzdesi, tam sayıya yuvarlanır. Aylık fiyat sıfır ya da geçersizse 0. */
export function savingsPercent(monthly: number, yearlyEquivalent: number): number {
  if (!Number.isFinite(monthly) || !Number.isFinite(yearlyEquivalent)) return 0;
  const percent = math.percent(math.sub(monthly, yearlyEquivalent), monthly);
  return percent === null ? 0 : math.round(percent, 0);
}

/** Yıl boyunca biriken tasarruf: (aylık − yıllık eşdeğer) × 12. Negatif çıkarsa 0. */
export function yearlySavings(monthly: number, yearlyEquivalent: number): number {
  return math.max(0, math.mul(math.sub(monthly, yearlyEquivalent), 12)) ?? 0;
}

/* Tasarruf notunu yeniden renklendirmek için herhangi bir üst öğede --billing-accent değerini ez. */
.root {
  --_accent: var(--billing-accent, var(--success));
  --_h: 34px;
  --_pad: 3px;
  position: relative;
  isolation: isolate;
  display: inline-flex;
  max-width: 100%;
  align-items: center;
  padding: var(--_pad);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-pill);
  background: var(--surface-muted);
  font-family: var(--font-body);
  font-size: var(--text-sm);
  letter-spacing: var(--tracking-body);
  line-height: 1;
}
.root[data-size="lg"] { --_h: 42px; --_pad: 4px; font-size: var(--text-base); }

/* Bütün iz için tek başparmak. Konumu ve genişliği seçili seçenekten ölçülür. */
.thumb,
.thumbStatic {
  position: absolute;
  z-index: -1;
  border-radius: var(--radius-pill);
  background: var(--surface-raised);
  box-shadow: 0 0 0 1px var(--border-subtle), 0 1px 2px oklch(0% 0 0 / .06), 0 2px 6px oklch(0% 0 0 / .04);
  pointer-events: none;
}
.thumb { top: var(--_pad); bottom: var(--_pad); left: 0; will-change: transform, width; }
.thumbStatic { inset: 0; }
:global(:root[data-theme="dark"]) .thumb,
:global(:root[data-theme="dark"]) .thumbStatic {
  box-shadow: 0 0 0 1px var(--border), inset 0 1px 0 oklch(100% 0 0 / .05), 0 1px 2px oklch(0% 0 0 / .3);
}

.option {
  position: relative;
  display: inline-flex;
  min-width: 0;
  height: var(--_h);
  align-items: center;
  padding: 0 14px;
  border: 0;
  border-radius: var(--radius-pill);
  background: transparent;
  color: var(--text-muted);
  font: inherit;
  letter-spacing: inherit;
  white-space: nowrap;
  cursor: pointer;
  transition: color var(--duration-fast) var(--ease-standard);
  -webkit-tap-highlight-color: transparent;
}
.option[data-selected] { color: var(--foreground); cursor: default; }
.option:has(.badge) { padding-right: 5px; }
.root[data-size="lg"] .option { padding-inline: 18px; }
.root[data-size="lg"] .option:has(.badge) { padding-right: 6px; }

@media (hover: hover) and (pointer: fine) {
  .option:not([data-selected]):hover { color: var(--text-secondary); }
}

.content {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: transform var(--duration-fast) var(--ease-standard);
}
.option:not([data-selected]):active .content { transform: scale(.97); }

.label { font-weight: 500; }

/* Tasarruf notu: seçeneği seçilene kadar sakin durur, sonra vurgu tonunu alır. */
.badge {
  display: inline-flex;
  height: calc(var(--_h) - 10px);
  align-items: center;
  padding: 0 8px;
  border-radius: var(--radius-pill);
  background: color-mix(in oklab, var(--foreground) 6%, transparent);
  color: var(--text-secondary);
  font-size: var(--text-xs);
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  transition: background-color var(--duration-standard) var(--ease-standard), color var(--duration-standard) var(--ease-standard);
}
.badge[data-active] {
  background: color-mix(in oklab, var(--_accent) 13%, transparent);
  color: color-mix(in oklab, var(--_accent) 88%, var(--foreground));
}
:global(:root[data-theme="dark"]) .badge[data-active] {
  background: color-mix(in oklab, var(--_accent) 18%, transparent);
  color: var(--_accent);
}

/* Üst üste değişim: her aday hücreyi ayırır, görünen aday üstte çapraz solar. */
.swap { position: relative; display: inline-grid; justify-items: center; overflow-y: clip; overflow-clip-margin: 2px; }
.swapSizer { grid-area: 1 / 1; visibility: hidden; }
.swapText { grid-area: 1 / 1; display: inline-block; }

@media (prefers-reduced-motion: reduce) {
  .content, .badge { transition: none; }
}

/* ------------------------------------------------------------------------ Price */

.price { display: inline-flex; min-width: 0; flex-wrap: wrap; align-items: flex-end; gap: 4px 10px; }
.amount {
  display: inline-flex;
  align-items: flex-start;
  color: var(--foreground);
  font-family: var(--font-display);
  font-size: var(--text-3xl);
  font-weight: 400;
  letter-spacing: var(--tracking-display);
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.currency { margin-top: .12em; margin-right: .04em; color: var(--text-secondary); font-size: .55em; }
.counter { display: inline-flex; }
.counter > span { font: inherit !important; letter-spacing: inherit !important; }
.aside {
  display: inline-flex;
  align-items: baseline;
  padding-bottom: .3em;
  color: var(--text-muted);
  font-size: var(--text-sm);
  line-height: var(--leading-body);
  white-space: nowrap;
}
.wasSlot { display: inline-block; overflow-x: clip; }
.was { display: inline-block; padding-right: 6px; color: var(--text-muted); font-variant-numeric: tabular-nums; text-decoration-thickness: 1px; }
.period { position: relative; display: inline-block; overflow-x: clip; overflow-clip-margin: 2px; }
.periodSizer { display: inline-block; visibility: hidden; }
.periodText { position: absolute; top: 0; left: 0; display: inline-block; }

"use client";

import { useCallback, useLayoutEffect, useRef, useState, type KeyboardEvent } from "react";
import { AnimatePresence, motion, useReducedMotion, type Transition, type Variants } from "motion/react";
import { AnimatedCounter } from "../animated-counter/animated-counter";
import { motionTokens } from "../lib/motion-tokens";
import { currencyPrefix, formatPrice } from "./billing-format";
import styles from "./billing-toggle.module.css";

export interface BillingToggleOption {
  value: string;
  label: string;
  /** Kısa tasarruf notu, örneğin "%20 indirim". */
  badge?: string;
  /** Bu seçenek seçilince rozet metni, örneğin "₺576 kazanırsınız". Verilmezse `badge` kullanılır. */
  activeBadge?: string;
}

export interface BillingToggleProps {
  value: string;
  onValueChange: (value: string) => void;
  options?: BillingToggleOption[];
  /** Grubun erişilebilir adı. */
  label?: string;
  size?: "md" | "lg";
  className?: string;
}

const { duration, ease, blur } = motionTokens;

/** Kritik sönümlü: başparmak aşmadan kayar ve yerine oturur. */
const glide: Transition = { type: "spring", visualDuration: 0.34, bounce: 0 };

const DEFAULT_OPTIONS: BillingToggleOption[] = [
  { value: "monthly", label: "Aylık" },
  { value: "yearly", label: "Yıllık", badge: "%20 indirim" },
];

const swap: Variants = {
  hidden: { opacity: 0, y: "0.45em", filter: `blur(${blur.subtle}px)` },
  shown: { opacity: 1, y: 0, filter: "blur(0px)", transition: { duration: duration.standard, ease: [...ease.enter] } },
  gone: { opacity: 0, y: "-0.45em", filter: `blur(${blur.subtle}px)`, transition: { duration: duration.fast, ease: [...ease.standard] } },
};
const still: Variants = { hidden: { opacity: 0 }, shown: { opacity: 1, transition: { duration: duration.fast } }, gone: { opacity: 0, transition: { duration: 0 } } };

/**
 * Yerinde değişen metin. Bütün adaylar aynı ızgara hücresinde durur; kutu en uzun adayın genişliğinde kalır
 * ve metin değişince çevresindeki hiçbir şey kaymaz.
 */
function StableSwap({ text, candidates, reduced, className }: { text: string; candidates: string[]; reduced: boolean; className?: string }) {
  return (
    <span className={[styles.swap, className].filter(Boolean).join(" ")}>
      {[...new Set(candidates)].map(candidate => <span key={candidate} className={styles.swapSizer} aria-hidden="true">{candidate}</span>)}
      <AnimatePresence initial={false}>
        <motion.span key={text} className={styles.swapText} variants={reduced ? still : swap} initial="hidden" animate="shown" exit="gone">{text}</motion.span>
      </AnimatePresence>
    </span>
  );
}

type Thumb = { x: number; width: number };

/**
 * Faturalama dönemi anahtarı. Tek bir başparmak seçenekler arasında kritik sönümlü yayla kayar;
 * ucuz dönemin tasarruf notu seçilince renklenir ve yerinde yeniden yazılır.
 */
export function BillingToggle({ value, onValueChange, options = DEFAULT_OPTIONS, label = "Faturalama dönemi", size = "md", className }: BillingToggleProps) {
  const reduced = !!useReducedMotion();
  const rootRef = useRef<HTMLDivElement>(null);
  const refs = useRef<Array<HTMLButtonElement | null>>([]);
  const [thumb, setThumb] = useState<Thumb | null>(null);
  const selectedIndex = Math.max(0, options.findIndex(option => option.value === value));

  const measure = useCallback(() => {
    const node = refs.current[selectedIndex];
    if (!node) return;
    setThumb(current => current && current.x === node.offsetLeft && current.width === node.offsetWidth ? current : { x: node.offsetLeft, width: node.offsetWidth });
  }, [selectedIndex]);

  useLayoutEffect(() => {
    measure();
    const root = rootRef.current;
    if (!root || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(measure);
    observer.observe(root);
    return () => observer.disconnect();
  }, [measure]);

  const onKeyDown = (event: KeyboardEvent<HTMLButtonElement>, index: number) => {
    const step = event.key === "ArrowRight" || event.key === "ArrowDown" ? 1 : event.key === "ArrowLeft" || event.key === "ArrowUp" ? -1 : 0;
    const target = event.key === "Home" ? 0 : event.key === "End" ? options.length - 1 : step ? (index + step + options.length) % options.length : -1;
    if (target < 0) return;
    event.preventDefault();
    onValueChange(options[target]!.value);
    refs.current[target]?.focus();
  };

  return (
    <div ref={rootRef} role="radiogroup" aria-label={label} className={[styles.root, className].filter(Boolean).join(" ")} data-size={size}>
      {thumb ? (
        <motion.span
          className={styles.thumb}
          aria-hidden="true"
          initial={false}
          animate={{ x: thumb.x, width: thumb.width }}
          transition={reduced ? { duration: 0 } : glide}
        />
      ) : null}
      {options.map((option, index) => {
        const selected = index === selectedIndex;
        const badgeText = selected ? option.activeBadge ?? option.badge : option.badge;
        const candidates = [option.badge, option.activeBadge].filter((text): text is string => !!text);
        return (
          <button
            key={option.value}
            ref={node => { refs.current[index] = node; }}
            type="button"
            role="radio"
            aria-checked={selected}
            tabIndex={selected ? 0 : -1}
            className={styles.option}
            data-selected={selected || undefined}
            onClick={() => onValueChange(option.value)}
            onKeyDown={event => onKeyDown(event, index)}
          >
            {selected && !thumb ? <span className={styles.thumbStatic} aria-hidden="true" /> : null}
            <span className={styles.content}>
              <span className={styles.label}>{option.label}</span>
              {badgeText ? (
                <span className={styles.badge} data-active={selected || undefined}>
                  <StableSwap text={badgeText} candidates={candidates} reduced={reduced} />
                </span>
              ) : null}
            </span>
          </button>
        );
      })}
    </div>
  );
}

export interface BillingPriceProps {
  amount: number;
  /** ISO para birimi kodu (ABACUS): "TRY", "USD", "EUR". Varsayılan "TRY". */
  currency?: string;
  /** Fiyatın ardından gelen dönem, örneğin "ayda". Değişince yerinde değişir. */
  period?: string;
  /** Önceki fiyat; `amount` değerinden yüksekse üstü çizili gösterilir. */
  was?: number;
  decimals?: number;
  className?: string;
}

const clip: Transition = { type: "spring", visualDuration: 0.36, bounce: 0 };

/** Yeni tutara dönen fiyat. Eski fiyat ve dönem genişliğini yumuşakça değiştirir; yanlarındaki hiçbir şey sıçramaz. */
export function BillingPrice({ amount, currency = "TRY", period, was, decimals = 0, className }: BillingPriceProps) {
  const reduced = !!useReducedMotion();
  const showWas = was !== undefined && was > amount;
  const periodRef = useRef<HTMLSpanElement>(null);
  const [periodWidth, setPeriodWidth] = useState<number | null>(null);

  useLayoutEffect(() => {
    const sizer = periodRef.current;
    if (sizer) setPeriodWidth(sizer.offsetWidth);
  }, [period]);

  return (
    <span className={[styles.price, className].filter(Boolean).join(" ")}>
      <span className={styles.amount}>
        <span className={styles.currency}>{currencyPrefix(currency)}</span>
        <span className={styles.counter}><AnimatedCounter value={amount} decimals={decimals} /></span>
      </span>
      <span className={styles.aside}>
        <AnimatePresence initial={false}>
          {showWas ? (
            <motion.span
              key="was"
              className={styles.wasSlot}
              initial={reduced ? { opacity: 0 } : { opacity: 0, width: 0 }}
              animate={{ opacity: 1, width: "auto" }}
              exit={reduced ? { opacity: 0, transition: { duration: 0 } } : { opacity: 0, width: 0, transition: { ...clip, opacity: { duration: duration.fast } } }}
              transition={reduced ? { duration: duration.fast } : { ...clip, opacity: { duration: duration.standard, ease: [...ease.enter] } }}
            >
              <del className={styles.was}>{formatPrice(was, currency, decimals)}</del>
            </motion.span>
          ) : null}
        </AnimatePresence>
        {period ? (
          <motion.span
            className={styles.period}
            initial={false}
            animate={periodWidth === null ? undefined : { width: periodWidth }}
            transition={reduced ? { duration: 0 } : clip}
          >
            <span ref={periodRef} className={styles.periodSizer} aria-hidden="true">{period}</span>
            <AnimatePresence initial={false}>
              <motion.span key={period} className={styles.periodText} variants={reduced ? still : swap} initial="hidden" animate="shown" exit="gone">{period}</motion.span>
            </AnimatePresence>
          </motion.span>
        ) : null}
      </span>
    </span>
  );
}

export default BillingToggle;
